def gen(rng):
    def make(n, k, lo=-10**9, hi=10**9):
        s = sorted(rng.randint(lo, hi) for _ in range(n))
        keys = [(i + rng.randint(0, k), i) for i in range(n)]
        order = sorted(range(n), key=lambda i: keys[i])
        a = [s[i] for i in order]
        return str(n) + ' ' + str(k) + '\n' + ' '.join(map(str, a))
    tests = ['1 0\n5', '2 1\n9 -3', '3 0\n1 2 3', '4 3\n4 3 2 1', '5 1\n2 1 4 3 5', '7 2\n3 1 2 6 4 5 7']
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(3):
            k = rng.randint(0, n - 1)
            if rng.random() < 0.5:
                tests.append(make(n, k, -5, 5))
            else:
                tests.append(make(n, k, -50, 50))
    n = 100000
    tests.append(make(n, 3))
    tests.append(make(n, 100))
    tests.append(make(n, 5000))
    tests.append(make(n, n - 1))
    tests.append(make(n, 0))
    tests.append(make(n, 20, -3, 3))
    return tests

